/// <summary>
/// designed by AVANADE WEN
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(SalesQuotationCopying, AVABuildingProjectId), FormControlEventType::Modified)]
public static void AVABuildingProjectId_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormRun         formRun = sender.formRun();
    FormDataSource  sqt_ds = formRun.dataSource(formdatasourcestr(SalesQuotationCopying, SalesQuotationTable));
    QueryBuildRange qbr = SysQuery::findOrCreateRange(sqt_ds.query().dataSourceTable(tableNum(SalesQuotationTable)),fieldNum(SalesQuotationTable, KCS_KBVBuildingProjectID));
    qbr.value(SysQuery::value(sender.valueStr()));
    sqt_ds.executeQuery();

}

